},\n    left=16pt, right=14pt, top=4pt, bottom=4pt,\n    fonttitle=\\fontsize{42}{50}\\selectfont\\bfseries\\color{white},\n    coltitle=white, colbacktitle=primary,\n    toptitle=8pt, bottomtitle=8pt,\n    valign=top, drop shadow={opacity=0.22},\n  },\n}\n\n\\begin{document}\n\\begin{tcbposter}[\n  coverage={spread},\n  poster={columns=3, rows=20, spacing=0mm},\n]\n\n% ══════════════════════════════════════\n% TITLE BAR (rows top to row3)\n% ══════════════════════════════════════\n\\posterbox[\n  enhanced, colback=primary, colframe=primary, colupper=white,\n  arc=0pt, boxrule=0pt,\n  left=40pt, right=40pt, top=16pt, bottom=12pt,\n  halign=center, valign=center,\n  drop shadow={opacity=0.3}\n]{name=title, column=1, span=3, between=top and row4}{\n  {\\fontsize{80}{96}\\selectfont\\bfseries 300 Years of Sclerosponge Thermometry Shows}\\\\[10pt]\n  {\\fontsize{80}{96}\\selectfont\\bfseries Global Warming Has Exceeded 1.5\\,\\textdegree C}\\\\[18pt]\n  {\\fontsize{36}{44}\\selectfont McCulloch, M.T. \\hspace{6pt}$\\cdot$\\hspace{6pt} Winter, A. \\hspace{6pt}$\\cdot$\\hspace{6pt} Sherman, C.E. \\hspace{6pt}$\\cdot$\\hspace{6pt} Trotter, J.A.}\\\\[10pt]\n  {\\fontsize{30}{38}\\selectfont\\color{white!75} \\textit{Nature Climate Change}, 2024 \\hspace{12pt}|\\hspace{12pt} AGU / Nature Climate Change Symposium}\n}\n\n% ══════════════════════════════════════\n% STAT BANNER (rows 4 to 6)\n% ══════════════════════════════════════\n\\posterbox[\n  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,\n  left=12pt, right=12pt, top=8pt, bottom=8pt,\n  valign=center, borderline south={3pt}{0pt}{primary!35},\n]{name=stats, column=1, span=3, between=row4 and row6}{\n  \\centering\n  \\begin{minipage}[c]{0.31\\linewidth}\\centering\n    \\fcolorbox{secondary!50}{stathighlight}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{72}{86}\\selectfont\\bfseries\\color{secondary} {$>$1.5\\,\\textdegree C}}\\\\[6pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} Total warming from true}\\\\[2pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} pre-industrial baseline}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.31\\linewidth}\\centering\n    \\fcolorbox{accent!50}{statamber}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{72}{86}\\selectfont\\bfseries\\color{accent} +0.5\\,\\textdegree C}\\\\[6pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} Hidden warming already}\\\\[2pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} present by 1850--1900}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.31\\linewidth}\\centering\n    \\fcolorbox{oceandeep!50}{statblue}{\\parbox{0.88\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{72}{86}\\selectfont\\bfseries\\color{oceandeep} $\\sim$300\\,yr}\\\\[6pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} Continuous record from}\\\\[2pt]\n      {\\fontsize{28}{34}\\selectfont\\color{textdark} Caribbean sclerosponges}\\vspace{8pt}%\n    }}\n  \\end{minipage}\n}\n\n% ══════════════════════════════════════\n% COLUMN 1: Background + Methods + References\n% ══════════════════════════════════════\n\n% ── Why Sclerosponges? ──\n\\posterbox[coolcard, title={Why Sclerosponges?}\n]{name=background, column=1, between=row6 and row11}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{4pt}\n  Long-lived marine organisms in tropical oceans whose aragonite skeletons record ambient water temperature via \\textbf{Sr/Ca ratios}.\n\n  \\vspace{8pt}\n  \\colorbox{oceandeep!20}{\\parbox{0.94\\linewidth}{\\vspace{4pt}\\centering\n    {\\fontsize{32}{40}\\selectfont\\color{primary}\\textbf{Key Advantages}}\n  \\vspace{4pt}}}\n  \\vspace{6pt}\n\n  \\begin{itemize}[itemsep=10pt]\n    \\item \\textbf{Continuous growth} over centuries $\\to$ unbroken annual-resolution records\n    \\item \\textbf{Tropical ocean sensitivity} --- Caribbean sites capture large-scale SST variability\n    \\item \\textbf{Independent of instruments} --- extends record before 1850\n  \\end{itemize}\n}\n\n% ── Data & Methods ──\n\\posterbox[deepcard, title={Data \\& Methods}\n]{name=methods, column=1, between=row11 and row16}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{4pt}\n\n  \\colorbox{primary!20}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\n    {\\fontsize{32}{40}\\selectfont\\centering\n    \\textbf{Sampling:} Caribbean reef sites, 33--91\\,m depth}\n  \\vspace{6pt}}}\n  \\vspace{8pt}\n\n  \\colorbox{primary!20}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\n    {\\fontsize{32}{40}\\selectfont\\centering\n    \\textbf{Measurement:} Sr/Ca via ICP-OES}\n  \\vspace{6pt}}}\n  \\vspace{8pt}\n\n  \\colorbox{primary!20}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\n    {\\fontsize{32}{40}\\selectfont\\centering\n    \\textbf{Calibration:} vs.\\ instrumental SST ($r^2 > 0.9$)}\n  \\vspace{6pt}}}\n  \\vspace{8pt}\n\n  \\colorbox{primary!20}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\n    {\\fontsize{32}{40}\\selectfont\\centering\n    \\textbf{Validation:} HadCRUT5 \\& NOAA ERSSTv5}\n  \\vspace{6pt}}}\n  \\vspace{8pt}\n\n  \\begin{itemize}[itemsep=10pt]\n    \\item Excellent agreement in overlapping instrumental era\n    \\item Divergence before $\\sim$1850 reveals \\textbf{hidden warming}\n  \\end{itemize}\n}\n\n% ── References ──\n\\posterbox[coolcard, title={References}\n]{name=refs, column=1, between=row16 and row20}{\n  \\fontsize{30}{40}\\selectfont\n  \\vspace{4pt}\n  \\begin{enumerate}[itemsep=8pt, label={\\color{oceandeep}\\bfseries[\\arabic*]}]\n    \\item McCulloch et al.\\ (2024). Sclerosponge thermometry. \\textit{Nat.\\ Clim.\\ Change}.\n    \\item IPCC (2021). AR6 WG1: Physical Science Basis.\n    \\item Morice et al.\\ (2021). HadCRUT5. \\textit{J.\\ Geophys.\\ Res.}\n    \\item Huang et al.\\ (2017). NOAA ERSSTv5. \\textit{J.\\ Climate}.\n  \\end{enumerate}\n}\n\n% ══════════════════════════════════════\n% COLUMN 2: Timeline (HERO) + Key Finding\n% ══════════════════════════════════════\n\n% ── 300-Year Temperature Reconstruction (HERO) ──\n\\posterbox[warmcard, title={300-Year Temperature Reconstruction}\n]{name=timeline, column=2, between=row6 and row14}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{4pt}\n\n  \\colorbox{secondary!20}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{34}{42}\\selectfont\\color{secondary}\\textbf{Temperature Anomaly (\\textdegree C) vs.\\ True Pre-Industrial Baseline (1700--1790)}}\n  \\vspace{6pt}}}\n\n  \\vspace{10pt}\n\n  % Timeline visualization as structured table\n  \\centering\n  \\renewcommand{\\arraystretch}{2.0}\n  {\\fontsize{30}{38}\\selectfont\n  \\begin{tabular}{>{\\bfseries\\color{primary}}p{0.22\\linewidth} >{\\centering\\arraybackslash}p{0.18\\linewidth} p{0.50\\linewidth}}\n    \\rowcolor{oceandeep!15}\n    \\textsf{Period} & \\textsf{Anomaly} & \\textsf{Observation} \\\\\n    \\rowcolor{primary!8}\n    1700--1790 & \\colorbox{statblue}{\\textbf{0.0\\,\\textdegree C}} & Stable baseline --- true pre-industrial \\\\\n    \\rowcolor{primary!15}\n    1790--1850 & \\colorbox{statamber}{\\textbf{+0.2\\,\\textdegree C}} & Early industrialisation onset \\\\\n    \\rowcolor{primary!8}\n    1850--1900 & \\colorbox{accent!25}{\\textbf{+0.5\\,\\textdegree C}} & IPCC ``pre-industrial'' already warm \\\\\n    \\rowcolor{primary!15}\n    1900--1960 & \\colorbox{accent!35}{\\textbf{+0.7\\,\\textdegree C}} & Gradual warming; volcanic cooling \\\\\n    \\rowcolor{primary!8}\n    1960--2000 & \\colorbox{secondary!25}{\\textbf{+1.1\\,\\textdegree C}} & Accelerating trend; proxies converge \\\\\n    \\rowcolor{secondary!20}\n    2000--now & \\colorbox{secondary!40}{\\color{white}\\textbf{$>$1.5\\,\\textdegree C}} & \\textbf{Paris threshold exceeded} \\\\\n  \\end{tabular}}\n\n  \\vspace{10pt}\n\n  \\colorbox{secondary!25}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{34}{42}\\selectfont\\color{secondary}\\textbf{$\\Rightarrow$ 1.5\\,\\textdegree C crossed --- the warming we couldn't see}}\n  \\vspace{6pt}}}\n}\n\n% ── The Hidden 0.5 °C ──\n\\posterbox[ambercard, title={The Hidden 0.5\\,\\textdegree C}\n]{name=hidden, column=2, between=row14 and row20}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{6pt}\n\n  \\centering\n  \\renewcommand{\\arraystretch}{1.8}\n  {\\fontsize{32}{40}\\selectfont\n  \\begin{tabular}{p{0.44\\linewidth} >{\\centering\\arraybackslash}p{0.20\\linewidth} >{\\centering\\arraybackslash}p{0.22\\linewidth}}\n    \\rowcolor{accent!20}\n    \\textbf{Baseline} & \\textbf{Warming} & \\textbf{Source} \\\\\n    \\rowcolor{white}\n    1850--1900 (IPCC) & \\colorbox{statblue}{\\textbf{$\\sim$1.2\\,\\textdegree C}} & HadCRUT5 \\\\\n    \\rowcolor{secondary!15}\n    1700--1790 (true) & \\colorbox{secondary!35}{\\color{white}\\textbf{$\\sim$1.7\\,\\textdegree C}} & \\textbf{This study} \\\\\n    \\rowcolor{accent!15}\n    \\textbf{Difference} & \\colorbox{accent!35}{\\textbf{$\\sim$0.5\\,\\textdegree C}} & Hidden warming \\\\\n  \\end{tabular}}\n\n  \\vspace{12pt}\n\n  \\colorbox{secondary!30}{\\parbox{0.94\\linewidth}{\\vspace{8pt}\\centering\n    {\\fontsize{38}{46}\\selectfont\\color{secondary}\\textbf{IPCC baseline already contained}}\\\\[4pt]\n    {\\fontsize{38}{46}\\selectfont\\color{secondary}\\textbf{$\\sim$0.5\\,\\textdegree C of anthropogenic warming}}\n  \\vspace{8pt}}}\n\n  \\vspace{8pt}\n\n  \\begin{itemize}[itemsep=10pt]\n    \\item Instrumental record \\textbf{systematically underestimates} total warming\n    \\item The ``pre-industrial'' was \\textbf{not truly pre-industrial}\n  \\end{itemize}\n}\n\n% ══════════════════════════════════════\n% COLUMN 3: Policy + Key Takeaways\n% ══════════════════════════════════════\n\n% ── Pre-Industrial Baseline Matters ──\n\\posterbox[warmcard, title={Pre-Industrial Baseline Matters}\n]{name=keyfinding, column=3, between=row6 and row11}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{4pt}\n\n  \\colorbox{secondary!22}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{32}{40}\\selectfont\\color{secondary}\\textbf{The Paris Agreement uses ``pre-industrial levels'' ---}}\\\\[3pt]\n    {\\fontsize{32}{40}\\selectfont\\color{secondary}\\textbf{but the IPCC operationally uses 1850--1900}}\n  \\vspace{6pt}}}\n\n  \\vspace{10pt}\n\n  \\begin{itemize}[itemsep=10pt]\n    \\item Sclerosponges reveal warming \\textbf{began before 1850}\n    \\item 1850--1900 was already \\textbf{$\\sim$0.5\\,\\textdegree C above} the 1700--1790 mean\n    \\item Conventional estimates miss \\textbf{early anthropogenic signal}\n  \\end{itemize}\n\n  \\vspace{8pt}\n  \\colorbox{accent!22}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{34}{42}\\selectfont\\color{accent}\\textbf{$\\Rightarrow$ Baseline choice changes everything}}\n  \\vspace{6pt}}}\n}\n\n% ── Policy & Climate Target Implications ──\n\\posterbox[ambercard, title={Policy \\& Climate Target Implications}\n]{name=policy, column=3, between=row11 and row16}{\n  \\fontsize{34}{44}\\selectfont\n  \\vspace{4pt}\n\n  \\colorbox{accent!22}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{32}{40}\\selectfont\\color{accent}\\textbf{Remaining Carbon Budget for 1.5\\,\\textdegree C}}\\\\[3pt]\n    {\\fontsize{48}{56}\\selectfont\\color{secondary}\\textbf{$\\approx$ Zero}}\n  \\vspace{6pt}}}\n\n  \\vspace{10pt}\n\n  \\begin{itemize}[itemsep=10pt]\n    \\item 1.5\\,\\textdegree C target is \\textbf{already exceeded}\n    \\item 2.0\\,\\textdegree C guardrail: only \\textbf{$\\sim$0.3\\,\\textdegree C} remaining (not $\\sim$0.8\\,\\textdegree C)\n    \\item \\textbf{Urgent:} transparent baseline communication needed\n  \\end{itemize}\n\n  \\vspace{8pt}\n  \\colorbox{secondary!25}{\\parbox{0.94\\linewidth}{\\vspace{6pt}\\centering\n    {\\fontsize{32}{40}\\selectfont\\color{secondary}\\textbf{Rapid emissions reductions are imperative}}\n  \\vspace{6pt}}}\n}\n\n% ── Key Takeaways ──\n\\posterbox[highlightcard, title={Key Takeaways}\n]{name=takeaways, column=3, between=row16 and row20}{\n  \\fontsize{34}{44}\\selectfont\\color{textdark}\n  \\vspace{6pt}\n\n  \\begin{enumerate}[itemsep=12pt, label={\\color{white}\\fcolorbox{primary}{primary}{\\bfseries\\footnotesize\\arabic*}}]\n    \\item Sclerosponge Sr/Ca proxies provide \\textbf{300-year} continuous SST records\n    \\item \\textbf{$\\sim$0.5\\,\\textdegree C} of warming occurred \\textbf{before} the conventional 1850--1900 baseline\n    \\item The \\textbf{1.5\\,\\textdegree C} Paris target has \\textbf{already been surpassed}\n    \\item Remaining carbon budgets are \\textbf{significantly smaller} than IPCC estimates\n  \\end{enumerate}\n\n  \\vspace{8pt}\n  \\centering\n  {\\fontsize{30}{38}\\selectfont\\color{textgray} McCulloch et al.\\ (2024) --- \\textit{Nature Climate Change}}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 387, "startLine": 1, "totalLines": 387}}

