\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Climate Science Color Theme ──
% Cool-to-warm: deep ocean blues → warming reds/ambers
\definecolor{primary}{HTML}{0C2D48}      % deep ocean navy
\definecolor{secondary}{HTML}{B91C1C}    % warming red
\definecolor{accent}{HTML}{D97706}       % amber/warming
\definecolor{bgposter}{HTML}{E8EEF4}     % cool pale blue-gray
\definecolor{redbg}{HTML}{FFF5F3}        % warm pink tint
\definecolor{bluebg}{HTML}{EDF2F8}       % cool blue tint
\definecolor{darkbg}{HTML}{F0F4F8}       % slate tint
\definecolor{amberbg}{HTML}{FFFBF0}      % warm amber tint
\definecolor{redtitlebg}{HTML}{FDEAE8}   % card title tint warm
\definecolor{bluetitlebg}{HTML}{DCE6F2}  % card title tint cool
\definecolor{darktitlebg}{HTML}{D4DEE8}  % card title tint slate
\definecolor{ambertitlebg}{HTML}{FDF3DC} % card title tint amber
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEE8E8}
\definecolor{statblue}{HTML}{DBEAFE}
\definecolor{statamber}{HTML}{FEF3C7}
\definecolor{oceandeep}{HTML}{145374}    % medium ocean blue
\definecolor{warmred}{HTML}{DC2626}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{oceandeep}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  warmcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  coolcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{oceandeep},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{oceandeep},
    coltitle=oceandeep, colbacktitle=bluetitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={oceandeep!50},
    valign=top, drop shadow={opacity=0.18},
  },
  deepcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{42}{50}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════
% TITLE BAR (rows top to row3)
% ══════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{80}{96}\selectfont\bfseries 300 Years of Sclerosponge Thermometry Shows}\\[10pt]
  {\fontsize{80}{96}\selectfont\bfseries Global Warming Has Exceeded 1.5\,\textdegree C}\\[18pt]
  {\fontsize{36}{44}\selectfont McCulloch, M.T. \hspace{6pt}$\cdot$\hspace{6pt} Winter, A. \hspace{6pt}$\cdot$\hspace{6pt} Sherman, C.E. \hspace{6pt}$\cdot$\hspace{6pt} Trotter, J.A.}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!75} \textit{Nature Climate Change}, 2024 \hspace{12pt}|\hspace{12pt} AGU / Nature Climate Change Symposium}
}

