\posterbox[warmcard, title={300-Year Temperature Reconstruction}
]{name=timeline, column=2, between=row6 and row14}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\vspace{6pt}\centering
    {\fontsize{34}{42}\selectfont\color{secondary}\textbf{Temperature Anomaly (\textdegree C) vs.\ True Pre-Industrial Baseline (1700--1790)}}
  \vspace{6pt}}}

  \vspace{10pt}

  % Timeline visualization as structured table
  \centering
  \renewcommand{\arraystretch}{2.0}
  {\fontsize{30}{38}\selectfont
  \begin{tabular}{>{\bfseries\color{primary}}p{0.22\linewidth} >{\centering\arraybackslash}p{0.18\linewidth} p{0.50\linewidth}}
    \rowcolor{oceandeep!15}
    \textsf{Period} & \textsf{Anomaly} & \textsf{Observation} \\
    \rowcolor{primary!8}
    1700--1790 & \colorbox{statblue}{\textbf{0.0\,\textdegree C}} & Stable baseline --- true pre-industrial \\
    \rowcolor{primary!15}
    1790--1850 & \colorbox{statamber}{\textbf{+0.2\,\textdegree C}} & Early industrialisation onset \\
    \rowcolor{primary!8}
    1850--1900 & \colorbox{accent!25}{\textbf{+0.5\,\textdegree C}} & IPCC ``pre-industrial'' already warm \\
    \rowcolor{primary!15}
    1900--1960 & \colorbox{accent!35}{\textbf{+0.7\,\textdegree C}} & Gradual warming; volcanic cooling \\
    \rowcolor{primary!8}
    1960--2000 & \colorbox{secondary!25}{\textbf{+1.1\,\textdegree C}} & Accelerating trend; proxies converge \\
    \rowcolor{secondary!20}
    2000--now & \colorbox{secondary!40}{\color{white}\textbf{$>$1.5\,\textdegree C}} & \textbf{Paris threshold exceeded} \\
  \end{tabular}}

  \vspace{10pt}

  \colorbox{secondary!25}{\parbox{0.94\linewidth}{\vspace{6pt}\centering
    {\fontsize{34}{42}\selectfont\color{secondary}\textbf{$\Rightarrow$ 1.5\,\textdegree C crossed --- the warming we couldn't see}}
  \vspace{6pt}}}
}

